namespace Monstey_LeaveOwned {
using Monstey_U64=std::uint64_t;
using Monstey_Result=Monstey::Monstey_GadbManagerLeaveProjectionResult;
using Monstey_Raw=Monstey::Monstey_GadbBufferedResult;
struct Monstey_Stats {unsigned cases=0,checks=0,faults=0,calls=0;std::vector<std::string> labels;std::vector<std::array<Monstey_U64,4>> outputs;} Monstey_Statistics;
void Monstey_Check(bool v,const std::string&why){++Monstey_Statistics.checks;if(!v)throw std::runtime_error(why);}
void Monstey_Start(const std::string&label){++Monstey_Statistics.cases;Monstey_Statistics.labels.push_back(label);}
bool Monstey_RawEqual(Monstey_Raw a,Monstey_Raw b){return a.rax==b.rax&&a.rdx==b.rdx;}
bool Monstey_ResultEqual(Monstey_Result a,Monstey_Result b){return Monstey_RawEqual(a.raw,b.raw)&&a.post_leave_r8==b.post_leave_r8&&a.post_leave_r9==b.post_leave_r9;}
constexpr Monstey_Raw Monstey_Incoming{0x8123456789ABCDEFULL,0xFEDC0123456789ABULL};
constexpr Monstey_Result Monstey_Output{{0xA102030405060708ULL,0xB112131415161718ULL},0xC122232425262728ULL,0xD132333435363738ULL};
constexpr Monstey_Result Monstey_Nested{{0x1122334455667788ULL,0x8877665544332211ULL},0x100000000ULL,0xFFFFFFFFFFFFFFFFULL};
void Monstey_WriteBytes(std::vector<std::uint8_t>&v,Monstey_U64 base,Monstey_U64 a,Monstey_U64 x){for(unsigned n=0;n<8;++n)v.at(static_cast<std::size_t>(a-base)+n)=static_cast<std::uint8_t>(x>>(8*n));}
struct Monstey_Fixture {
 Monstey_U64 base,guard,cell,lock=0x456789ABCDEF0123ULL,target=0x789ABCDEF0123456ULL;std::vector<std::uint8_t> bytes;Monstey::Monstey_GadbManagerPrimitiveBindings bindings;Monstey::Monstey_GadbManagerLeaveProjectionServices services;unsigned calls=0;Monstey_Result output=Monstey_Output;
 explicit Monstey_Fixture(Monstey_U64 b=0x1000):base(b),guard(b+8),cell(b+40),bytes(96){for(std::size_t n=0;n<bytes.size();++n)bytes[n]=static_cast<std::uint8_t>((n*37+0xA7)&255);bindings.leave_cell=cell;Monstey_Write(guard,lock);Monstey_Write(cell,target);services.leave=[this](Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q){Monstey_Validate(m,q,lock,target);return output;};}
 Monstey::Monstey_GadbBinderMemory Monstey_Memory(){return {base,bytes};}
 void Monstey_Write(Monstey_U64 a,Monstey_U64 x){Monstey_WriteBytes(bytes,base,a,x);}
 Monstey_U64 Monstey_Read(Monstey_U64 a)const{Monstey_U64 x=0;for(unsigned n=0;n<8;++n)x|=Monstey_U64(bytes.at(static_cast<std::size_t>(a-base)+n))<<(8*n);return x;}
 void Monstey_Validate(Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q,Monstey_U64 expectedLock,Monstey_U64 expectedTarget){++calls;++Monstey_Statistics.calls;Monstey_Check(m.base==base&&m.bytes.data()==bytes.data()&&m.bytes.size()==bytes.size(),"exact borrowed image");Monstey_Check(q.operation==Monstey::Monstey_GadbManagerSyncOperation::leave&&q.native_site==0x14114BA88ULL,"leave role/site");Monstey_Check(q.slot_identity==bindings.leave_cell&&q.target_identity==expectedTarget,"live cell/target DTO");Monstey_Check(q.critical_section==expectedLock,"actual lock DTO");Monstey_Check(Monstey_RawEqual(q.incoming,Monstey_Incoming),"incoming Raw2 unchanged, RDX is not assigned lock");}
 Monstey_Result Monstey_Run(bool destroy){auto v=destroy?Monstey::Monstey_GadbDestroyManagerGuardProjected(Monstey_Memory(),guard,Monstey_Incoming,bindings,services):Monstey::Monstey_GadbLeaveManagerCriticalSectionProjected(Monstey_Memory(),lock,Monstey_Incoming,bindings,services);Monstey_Statistics.outputs.push_back({v.raw.rax,v.raw.rdx,v.post_leave_r8,v.post_leave_r9});return v;}
};
void Monstey_Normal(){
 const std::array<Monstey_Result,3> values{{Monstey_Output,Monstey_Nested,{{0xFFFFFFFF00000000ULL,0x00000001FFFFFFFFULL},0xDEAD000000000000ULL,0xBEEF000000000001ULL}}};
 for(bool destroy:{false,true})for(std::size_t n=0;n<values.size();++n){Monstey_Start(std::string(destroy?"destroy":"direct")+" distinct_four64_"+std::to_string(n));Monstey_Fixture f;f.output=values[n];const auto before=f.bytes;Monstey_Check(Monstey_ResultEqual(f.Monstey_Run(destroy),values[n]),"all four full64 return words unchanged");Monstey_Check(f.bytes==before&&f.calls==1,"no own clear/free/store");}
 for(unsigned layout=0;layout<6;++layout){Monstey_Start("layout_"+std::to_string(layout));Monstey_Fixture f(layout==3||layout==4?0:0x1000);if(layout==0){f.guard=f.base+3;f.cell=f.base+19;}if(layout==1){f.cell=f.guard;}if(layout==2){f.cell=f.guard+4;}if(layout==3){f.guard=0;f.cell=24;}if(layout==4){f.guard=0;f.cell=0;f.target=0;}if(layout==5){f.lock=0;f.target=0;}f.bindings.leave_cell=f.cell;f.Monstey_Write(f.guard,f.lock);f.Monstey_Write(f.cell,f.target);f.lock=f.Monstey_Read(f.guard);f.target=f.Monstey_Read(f.cell);const auto before=f.bytes;Monstey_Check(Monstey_ResultEqual(f.Monstey_Run(true),f.output),"ordinary overlapping/unaligned/mapped0 layout");Monstey_Check(f.bytes==before&&f.calls==1,"layout image unchanged");}
 for(bool destroy:{false,true}){Monstey_Start(destroy?"destroy zero_target":"direct zero_target_unmapped_lock");Monstey_Fixture f;f.target=0;f.Monstey_Write(f.cell,0);if(!destroy)f.lock=std::numeric_limits<Monstey_U64>::max();const auto before=f.bytes;Monstey_Check(Monstey_ResultEqual(f.Monstey_Run(destroy),f.output),"target0 dispatch and no lock preflight");Monstey_Check(f.bytes==before,"target0 no own stores");}
 Monstey_Start("live_guard_and_cell_mutation_between_calls");Monstey_Fixture f;Monstey_Check(Monstey_ResultEqual(f.Monstey_Run(true),f.output),"initial live DTO");f.lock=0xFFFFFFFF76543210ULL;f.target=0x100000000ULL;f.Monstey_Write(f.guard,f.lock);f.Monstey_Write(f.cell,f.target);const auto before=f.bytes;Monstey_Check(Monstey_ResultEqual(f.Monstey_Run(true),f.output)&&f.calls==2,"live guard/cell reload");Monstey_Check(f.bytes==before,"second live call image");
}
void Monstey_Boundary(bool destroy,Monstey_Fixture&f,Monstey_U64 argument){const auto before=f.bytes;bool caught=false;try{static_cast<void>(f.Monstey_Run(destroy));}catch(const Monstey::Monstey_GadbManagerPrimitiveBoundaryFault&q){++Monstey_Statistics.faults;caught=q.kind==Monstey::Monstey_GadbManagerPrimitiveBoundaryKind::missing_sync_service&&q.native_site==0x14114BA88ULL&&q.address==f.bindings.leave_cell&&q.width==8&&q.slot_identity==f.bindings.leave_cell&&q.target_identity==f.Monstey_Read(f.bindings.leave_cell)&&q.argument==argument;}Monstey_Check(caught,"exact old M1 missing service fields");Monstey_Check(f.bytes==before&&f.calls==0,"missing service no writes/no invocation");}
void Monstey_Fault(bool destroy,Monstey_Fixture&f,Monstey_U64 address){const auto before=f.bytes;bool caught=false;try{static_cast<void>(f.Monstey_Run(destroy));}catch(const Monstey::Monstey_GadbBufferedMemoryFault&q){++Monstey_Statistics.faults;caught=q.address==address&&q.width==8&&!q.writing;}Monstey_Check(caught,"exact first full8byte read fault");Monstey_Check(f.bytes==before&&f.calls==0,"memory failure unchanged prefix");}
void Monstey_FaultCases(){
 for(bool destroy:{false,true}){Monstey_Start(destroy?"destroy missing_target0":"direct missing_target0");Monstey_Fixture f;f.services.leave={};f.target=0;f.Monstey_Write(f.cell,0);Monstey_Boundary(destroy,f,f.lock);}
 {Monstey_Start("guard_fault_precedes_cell_and_missing");Monstey_Fixture f;f.guard=f.base+92;f.bindings.leave_cell=f.base-1;f.services.leave={};Monstey_Fault(true,f,f.guard);}
 for(bool destroy:{false,true}){Monstey_Start(destroy?"destroy cell_fault_before_missing":"direct cell_fault_before_missing");Monstey_Fixture f;f.bindings.leave_cell=f.base+92;f.services.leave={};Monstey_Fault(destroy,f,f.bindings.leave_cell);}
 {Monstey_Start("guard_wrapped_fulloperand_fault");Monstey_Fixture f;f.guard=std::numeric_limits<Monstey_U64>::max()-3;f.services.leave={};Monstey_Fault(true,f,f.guard);}
 {Monstey_Start("cell_wrapped_fulloperand_fault");Monstey_Fixture f;f.bindings.leave_cell=std::numeric_limits<Monstey_U64>::max()-6;f.services.leave={};Monstey_Fault(false,f,f.bindings.leave_cell);}
 {Monstey_Start("high_numeric_arena_valid_unaligned");Monstey_Fixture f(std::numeric_limits<Monstey_U64>::max()-95);f.guard=f.base+9;f.cell=f.base+49;f.bindings.leave_cell=f.cell;f.Monstey_Write(f.guard,f.lock);f.Monstey_Write(f.cell,f.target);const auto before=f.bytes;Monstey_Check(Monstey_ResultEqual(f.Monstey_Run(true),f.output)&&f.bytes==before,"high full64 arena is not signed address rejection");}
}
struct Monstey_ProviderFailure:std::runtime_error{std::shared_ptr<const unsigned>token;explicit Monstey_ProviderFailure(std::shared_ptr<const unsigned>p):std::runtime_error("owned leave failure"),token(std::move(p)){};};
void Monstey_Effects(){
 for(bool destroy:{false,true}){Monstey_Start(destroy?"destroy provider_write_then_return":"direct provider_write_then_return");Monstey_Fixture f;auto expected=f.bytes;Monstey_WriteBytes(expected,f.base,f.guard,0xDEAD112233445566ULL);Monstey_WriteBytes(expected,f.base,f.cell,0xBEEF887766554433ULL);f.services.leave=[&f](Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q){f.Monstey_Validate(m,q,f.lock,f.target);f.Monstey_Write(f.guard,0xDEAD112233445566ULL);f.Monstey_Write(f.cell,0xBEEF887766554433ULL);return Monstey_Nested;};Monstey_Check(Monstey_ResultEqual(f.Monstey_Run(destroy),Monstey_Nested)&&f.bytes==expected,"provider stores retained, no postprimitive access");}
 for(bool destroy:{false,true}){Monstey_Start(destroy?"destroy typed_exception_prefix":"direct typed_exception_prefix");Monstey_Fixture f;const auto token=std::make_shared<const unsigned>(0x7531u);auto expected=f.bytes;Monstey_WriteBytes(expected,f.base,f.base+72,0x9988776655443322ULL);f.services.leave=[&f,token](Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q)->Monstey_Result{f.Monstey_Validate(m,q,f.lock,f.target);f.Monstey_Write(f.base+72,0x9988776655443322ULL);throw Monstey_ProviderFailure(token);};bool caught=false;try{static_cast<void>(f.Monstey_Run(destroy));}catch(const Monstey_ProviderFailure&q){++Monstey_Statistics.faults;caught=q.token==token&&std::string(q.what())=="owned leave failure";}Monstey_Check(caught&&f.bytes==expected&&f.calls==1,"dynamic exception type/shared token/fullimage, no rollback");}
}
struct Monstey_Retirement{unsigned*counter;~Monstey_Retirement(){++*counter;}};
void Monstey_Lifetime(){
 {Monstey_Start("persistent_mutable_shared_target");Monstey_Fixture f;f.services.leave=[&f,state=Monstey_U64{0}](Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q)mutable{f.Monstey_Validate(m,q,f.lock,f.target);++state;return Monstey_Result{{0xA000000000000000ULL+state,0xB000000000000000ULL+state},0xC000000000000000ULL+state,0xD000000000000000ULL+state};};const auto a=f.Monstey_Run(false);auto copied=f.services;const auto b=Monstey::Monstey_GadbDestroyManagerGuardProjected(f.Monstey_Memory(),f.guard,Monstey_Incoming,f.bindings,copied);const auto c=f.Monstey_Run(true);Monstey_Check(a.raw.rax==0xA000000000000001ULL&&b.raw.rax==0xA000000000000002ULL&&c.post_leave_r9==0xD000000000000003ULL,"value-captured state persists and copied holder shares target");}
 {Monstey_Start("self_replace_then_reenter_and_retire");unsigned retired=0;Monstey_Fixture f;auto hold=std::make_shared<Monstey_Retirement>();hold->counter=&retired;std::weak_ptr<Monstey_Retirement>weak=hold;f.services.leave=[owner=&f,hold,weak](Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q){auto*const fx=owner;const auto observed=weak;const auto outer=Monstey_Output;fx->Monstey_Validate(m,q,fx->lock,fx->target);fx->lock=0x1111222233334444ULL;fx->target=0;fx->Monstey_Write(fx->guard,fx->lock);fx->Monstey_Write(fx->cell,0);fx->services.leave=[fx](Monstey::Monstey_GadbBinderMemory child,const Monstey::Monstey_GadbManagerSyncCall&call){fx->Monstey_Validate(child,call,fx->lock,fx->target);return Monstey_Nested;};Monstey_Check(!observed.expired(),"active old target retained after replacement");const auto nested=fx->Monstey_Run(true);Monstey_Check(Monstey_ResultEqual(nested,Monstey_Nested),"reentry sees current replacement and live zero target");return outer;};hold.reset();const auto result=f.Monstey_Run(false);Monstey_Check(Monstey_ResultEqual(result,Monstey_Output)&&f.calls==2&&retired==1&&weak.expired(),"outer return unaffected and active old target retires by caller return");}
 {Monstey_Start("self_clear_nested_missing_then_retire");unsigned retired=0;Monstey_Fixture f;auto hold=std::make_shared<Monstey_Retirement>();hold->counter=&retired;std::weak_ptr<Monstey_Retirement>weak=hold;f.services.leave=[owner=&f,hold,weak](Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q){auto*const fx=owner;const auto observed=weak;const auto result=Monstey_Output;fx->Monstey_Validate(m,q,fx->lock,fx->target);fx->services.leave={};Monstey_Check(!observed.expired(),"active target retained through selfclear");bool missing=false;try{static_cast<void>(fx->Monstey_Run(true));}catch(const Monstey::Monstey_GadbManagerPrimitiveBoundaryFault&e){++Monstey_Statistics.faults;missing=e.native_site==0x14114BA88ULL&&e.slot_identity==fx->cell&&e.target_identity==fx->target&&e.argument==fx->lock;}Monstey_Check(missing,"nested call sees current empty binding");return result;};hold.reset();const auto out=f.Monstey_Run(false);Monstey_Check(Monstey_ResultEqual(out,Monstey_Output)&&retired==1&&weak.expired()&&f.calls==1,"cleared target retirement and actual one call");}
}
void Monstey_OldProjection(){for(bool destroy:{false,true}){Monstey_Start(destroy?"old_new_destroy_independent_raw2":"old_new_direct_independent_raw2");Monstey_Fixture fresh,old;auto expected=fresh.bytes;Monstey_WriteBytes(expected,fresh.base,fresh.base+72,0x1029384756ABCDEFULL);fresh.services.leave=[&fresh](Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q){fresh.Monstey_Validate(m,q,fresh.lock,fresh.target);fresh.Monstey_Write(fresh.base+72,0x1029384756ABCDEFULL);return Monstey_Nested;};Monstey::Monstey_GadbManagerPrimitiveServices services;services.sync=[&old](Monstey::Monstey_GadbBinderMemory m,const Monstey::Monstey_GadbManagerSyncCall&q){old.Monstey_Validate(m,q,old.lock,old.target);old.Monstey_Write(old.base+72,0x1029384756ABCDEFULL);return Monstey_Nested.raw;};const auto a=fresh.Monstey_Run(destroy);const auto b=destroy?Monstey::Monstey_GadbDestroyManagerGuard(old.Monstey_Memory(),old.guard,Monstey_Incoming,old.bindings,services):Monstey::Monstey_GadbLeaveManagerCriticalSection(old.Monstey_Memory(),old.lock,Monstey_Incoming,old.bindings,services);Monstey_Check(Monstey_RawEqual(a.raw,b)&&fresh.bytes==old.bytes&&fresh.bytes==expected,"truly independent old/new provider Raw2/fullimage projection");Monstey_Check(a.post_leave_r8==Monstey_Nested.post_leave_r8&&a.post_leave_r9==Monstey_Nested.post_leave_r9,"new extra words declared by new provider only");}}
std::string Monstey_Quote(const std::string&s){std::string out="\"";for(char c:s){if(c=='"'||c=='\\')out+='\\';if(c=='\n'){out+="\\n";continue;}out+=c;}return out+'"';}
std::string Monstey_Hex(Monstey_U64 n){std::ostringstream s;s<<std::hex<<std::setfill('0')<<std::setw(16)<<n;return s.str();}
void Monstey_Report(const char*path,bool pass,const std::string&error){std::ofstream f(path);f<<"{\n\"status\":"<<Monstey_Quote(pass?"PASS":"FAIL")<<",\n\"scope\":\"ACTUAL_FROZEN_LEAVE_PRODUCT_ADDITIONAL_DIRECT_POSITIVES\",\n\"cases\":"<<Monstey_Statistics.cases<<",\"checks\":"<<Monstey_Statistics.checks<<",\"faults\":"<<Monstey_Statistics.faults<<",\"primitive_calls\":"<<Monstey_Statistics.calls<<",\"error\":"<<Monstey_Quote(error)<<",\n\"labels\":[";bool first=true;for(const auto&s:Monstey_Statistics.labels){if(!first)f<<',';first=false;f<<Monstey_Quote(s);}f<<"],\n\"observed_four64_outputs\":[";first=true;for(const auto&v:Monstey_Statistics.outputs){if(!first)f<<',';first=false;f<<'[';for(unsigned n=0;n<4;++n){if(n)f<<',';f<<Monstey_Quote(Monstey_Hex(v[n]));}f<<']';}f<<"],\n\"Pub_reference_or_algorithm_read\":false,\"physical_ABI_OS_concurrency_parent235_or_fullgoal\":false,\"original_entrypoint_invoked\":false}\n";}
}
int main(int argc,char**argv){using namespace Monstey_LeaveOwned;if(argc!=2)return 2;try{Monstey_Normal();Monstey_FaultCases();Monstey_Effects();Monstey_Lifetime();Monstey_OldProjection();Monstey_Report(argv[1],true,"");std::cout<<"PASS "<<Monstey_Statistics.cases<<" cases "<<Monstey_Statistics.checks<<" checks\n";return 0;}catch(const std::exception&e){Monstey_Report(argv[1],false,e.what());std::cerr<<e.what()<<'\n';return 1;}catch(...){Monstey_Report(argv[1],false,"unexpected exception type");return 1;}}
